import json

# A tiny server that refuses requests until the handshake is complete
class Server:
    def __init__(self):
        self.state = "new"  # new -> initializing -> ready

    def handle(self, msg):
        method, mid = msg["method"], msg.get("id")
        if method == "initialize":
            self.state = "initializing"
            result = {"protocolVersion": "2025-06-18",
                      "capabilities": {"tools": {}},
                      "serverInfo": {"name": "demo", "version": "1.0"}}
            return {"jsonrpc": "2.0", "id": mid, "result": result}
        if method == "notifications/initialized":
            self.state = "ready"  # a notification: no reply is sent
            return None
        if self.state != "ready":  # reject early traffic
            return {"jsonrpc": "2.0", "id": mid,
                    "error": {"code": -32600, "message": "not initialized"}}
        if method == "tools/list":
            return {"jsonrpc": "2.0", "id": mid,
                    "result": {"tools": [{"name": "add"}]}}
        return {"jsonrpc": "2.0", "id": mid,
                "error": {"code": -32601, "message": "method not found"}}

server = Server()
steps = [
    {"jsonrpc": "2.0", "id": 1, "method": "tools/list"},  # too early
    {"jsonrpc": "2.0", "id": 2, "method": "initialize", "params": {}},
    {"jsonrpc": "2.0", "method": "notifications/initialized"},
    {"jsonrpc": "2.0", "id": 3, "method": "tools/list"},  # now allowed
]
for m in steps:
    print("->", json.dumps(m))
    r = server.handle(m)
    print("<-", json.dumps(r) if r else "(no reply)")

import json

def tool_add(args):
    return args["a"] + args["b"]

def handle(raw):
    # 1. Parse: bad JSON -> -32700 (id unknown, so null)
    try:
        msg = json.loads(raw)
    except ValueError:
        return {"jsonrpc": "2.0", "id": None,
                "error": {"code": -32700, "message": "parse error"}}
    # 2. Shape check -> -32600
    if not isinstance(msg, dict) or "method" not in msg:
        return {"jsonrpc": "2.0", "id": None,
                "error": {"code": -32600, "message": "invalid request"}}
    if "id" not in msg:
        return None  # notification: never answered
    mid, params = msg["id"], msg.get("params", {})
    if msg["method"] != "tools/call":
        return {"jsonrpc": "2.0", "id": mid,
                "error": {"code": -32601, "message": "method not found"}}
    args = params.get("arguments", {})
    if not isinstance(args.get("a"), int) or not isinstance(args.get("b"), int):
        return {"jsonrpc": "2.0", "id": mid,
                "error": {"code": -32602, "message": "invalid params"}}
    # Tool-level failures would be a normal result with isError true
    text = str(tool_add(args))
    return {"jsonrpc": "2.0", "id": mid,
            "result": {"content": [{"type": "text", "text": text}], "isError": False}}

inputs = [
    '{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"arguments":{"a":2,"b":3}}}',
    '{not json',
    '{"jsonrpc":"2.0","id":2}',
    '{"jsonrpc":"2.0","id":3,"method":"nope"}',
    '{"jsonrpc":"2.0","id":4,"method":"tools/call","params":{"arguments":{"a":"x"}}}',
    '{"jsonrpc":"2.0","method":"notifications/cancelled"}',
]
for raw in inputs:
    r = handle(raw)
    print(raw, "=>", json.dumps(r) if r else "(no reply)")
